<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\UserAccessTemporalCodeVersionVO;
use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\Holder\UserAccessTemporalCodeVersionAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAccessTemporalCodeVersionAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserAccessTemporalCodeVersionAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getVersion returns null on a freshly created holder.
         */
        public function testVersionNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithUserAccessTemporalCodeVersionAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isVersionAssigned());
            $this->assertNull($holder->getVersion());
        }
}
class ImplWithUserAccessTemporalCodeVersionAttributeHolderUnitTest
{
  use UserAccessTemporalCodeVersionAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedVersionRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultVersion();
    }}
